CREATE TABLE IF NOT EXISTS clients(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_auth(id TEXT PRIMARY KEY,client TEXT NOT NULL REFERENCES clients(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_shoots(client TEXT NOT NULL REFERENCES clients(id),session TEXT NOT NULL REFERENCES sessions(id),role TEXT NOT NULL,PRIMARY KEY(client,session));
CREATE TABLE IF NOT EXISTS shoot_urls(slug TEXT PRIMARY KEY,session TEXT NOT NULL UNIQUE REFERENCES sessions(id));
